select order_id, case when special_order_id is not null and report_month = '2026-08' and expected_balance <> 0 and ( sign_time is null or ( sign_time is not null and actual_balance = 0 ) ) then 0 when special_order_id is not null and report_month = '2026-08' and expected_balance <> 0 and sign_time is not null and actual_balance <> 0 then actual_balance else current_period_revenue end as adjusted_revenue from style_lab.complex_case_source;
